return ['domain'=>'pnscripts-product-tabs','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'PN Scripts Product Tabs 1.0.2','pot-creation-date'=>'2026-10-06T07:48:10+00:00','po-revision-date'=>'2026-10-04 00:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PN Scripts Product Tabs – Custom Tabs & FAQ'=>'PN Scripts Product Tabs – Custom Tabs & FAQ','https://pnscripts.com/marketplace/pn-product-tabs'=>'https://pnscripts.com/marketplace/pn-product-tabs','Custom product tabs per product, reusable global tabs by category or tag, FAQ tabs with optional FAQPage schema, rename, reorder or hide the default tabs, and a one-click importer from YIKES Custom Product Tabs. Works in classic and block themes.'=>'Eigene Produkt-Tabs pro Produkt, wiederverwendbare globale Tabs nach Kategorie oder Schlagwort, FAQ-Tabs mit optionalem FAQPage-Schema, Umbenennen, Sortieren oder Ausblenden der Standard-Tabs und ein Ein-Klick-Import aus YIKES Custom Product Tabs. Funktioniert mit klassischen und Block-Themes.','PN Scripts'=>'PN Scripts','https://pnscripts.com'=>'https://pnscripts.com','Tab settings'=>'Tab-Einstellungen','Tab type'=>'Tab-Typ','Rich text: the content written in the editor above'=>'Text: der Inhalt aus dem Editor oben','FAQ: questions and answers below'=>'FAQ: Fragen und Antworten unten','Add question'=>'Frage hinzufügen','Publish as FAQPage structured data'=>'Als strukturierte FAQPage-Daten ausgeben','Show this tab on'=>'Diesen Tab anzeigen bei','All products'=>'Alle Produkte','Products in these categories or with these tags'=>'Produkte in diesen Kategorien oder mit diesen Schlagwörtern','Only products where I add it (Product data → Custom tabs)'=>'Nur Produkte, bei denen ich ihn hinzufüge (Produktdaten → Eigene Tabs)','Categories (subcategories included)'=>'Kategorien (inklusive Unterkategorien)','Choose categories…'=>'Kategorien wählen …','Tags'=>'Schlagwörter','Choose tags…'=>'Schlagwörter wählen …','Position (priority)'=>'Position (Priorität)','Lower numbers come first. WooCommerce uses 10 for Description, 20 for Additional information and 30 for Reviews (change these under Products → Tab settings).'=>'Niedrigere Zahlen stehen zuerst. WooCommerce verwendet 10 für Beschreibung, 20 für Zusätzliche Informationen und 30 für Bewertungen (änderbar unter Produkte → Tab-Einstellungen).','Question'=>'Frage','Answer'=>'Antwort','Remove question'=>'Frage entfernen','Shown on'=>'Angezeigt bei','Type'=>'Typ','Priority'=>'Priorität','FAQ'=>'FAQ','Rich text'=>'Text','Products where added'=>'Produkte, bei denen er hinzugefügt wurde','No categories or tags chosen'=>'Keine Kategorien oder Schlagwörter gewählt','Custom tabs'=>'Eigene Tabs','Remove this tab? It is deleted when you update the product.'=>'Diesen Tab entfernen? Er wird beim Aktualisieren des Produkts gelöscht.','(no title)'=>'(kein Titel)','Tabs shown on this product, in this order (drag to reorder). Rich-text tabs accept anything the editor does; FAQ tabs show questions as an accessible list and can publish FAQPage structured data.'=>'Tabs dieses Produkts in dieser Reihenfolge (zum Sortieren ziehen). Text-Tabs akzeptieren alles, was der Editor kann; FAQ-Tabs zeigen Fragen als barrierefreie Liste und können strukturierte FAQPage-Daten ausgeben.','No custom tabs on this product yet.'=>'Dieses Produkt hat noch keine eigenen Tabs.','Add tab'=>'Tab hinzufügen','Add FAQ tab'=>'FAQ-Tab hinzufügen','Global tab to add'=>'Hinzuzufügender globaler Tab','Add a global tab…'=>'Globalen Tab hinzufügen …','Add'=>'Hinzufügen','Manage global tabs'=>'Globale Tabs verwalten','Global tabs shown automatically'=>'Automatisch angezeigte globale Tabs','Hide "%s" on this product'=>'„%s“ bei diesem Produkt ausblenden','WooCommerce tabs on this product'=>'WooCommerce-Tabs bei diesem Produkt','(deleted global tab)'=>'(gelöschter globaler Tab)','Global'=>'Global','Drag to reorder'=>'Zum Sortieren ziehen','Imported'=>'Importiert','Show'=>'Anzeigen','Remove'=>'Entfernen','Content comes from the global tab and updates everywhere when you edit it.'=>'Der Inhalt stammt aus dem globalen Tab und ändert sich überall, wenn Sie ihn bearbeiten.','Edit global tab'=>'Globalen Tab bearbeiten','Tab title'=>'Tab-Titel','Tab content'=>'Tab-Inhalt','Description'=>'Beschreibung','Additional information'=>'Zusätzliche Informationen','Reviews'=>'Bewertungen','Product tab settings'=>'Einstellungen der Produkt-Tabs','Settings'=>'Einstellungen','Global tabs'=>'Globale Tabs','Import the YIKES tabs now? YIKES data is not changed and you can undo the import.'=>'YIKES-Tabs jetzt importieren? Die YIKES-Daten bleiben unverändert und der Import kann rückgängig gemacht werden.','Remove all tabs created by the import (tabs you added yourself stay)?'=>'Alle vom Import erstellten Tabs entfernen (selbst angelegte Tabs bleiben)?','Working… %d products handled'=>'In Arbeit … %d Produkte verarbeitet','The request failed. Reload the page and try again.'=>'Die Anfrage ist fehlgeschlagen. Laden Sie die Seite neu und versuchen Sie es erneut.','Dry run finished: nothing was changed. These numbers are what an import will do.'=>'Probelauf beendet: Es wurde nichts geändert. Diese Zahlen zeigen, was ein Import tun wird.','Import finished. Check a few product pages, then deactivate YIKES Custom Product Tabs.'=>'Import abgeschlossen. Prüfen Sie einige Produktseiten und deaktivieren Sie dann YIKES Custom Product Tabs.','Import removed.'=>'Import entfernt.','… and %d more notes like these.'=>'… und %d weitere ähnliche Hinweise.','Products with YIKES tabs'=>'Produkte mit YIKES-Tabs','YIKES saved tabs'=>'Gespeicherte YIKES-Tabs','Global tabs to create / created'=>'Zu erstellende / erstellte globale Tabs','Saved tabs imported before (left as they are)'=>'Bereits importierte gespeicherte Tabs (bleiben unverändert)','Products to import / imported'=>'Zu importierende / importierte Produkte','Products unchanged since the last import (skipped)'=>'Seit dem letzten Import unveränderte Produkte (übersprungen)','Product tabs copied'=>'Kopierte Produkt-Tabs','Product tabs linked to a global tab'=>'Mit einem globalen Tab verknüpfte Produkt-Tabs','Tabs without a title (imported switched off)'=>'Tabs ohne Titel (deaktiviert importiert)','Tabs hidden by a duplicate title in YIKES (imported switched off)'=>'Durch doppelten Titel in YIKES verdeckte Tabs (deaktiviert importiert)','Default tabs YIKES replaced (hidden on those products)'=>'Von YIKES ersetzte Standard-Tabs (bei diesen Produkten ausgeblendet)','Imported global tabs removed'=>'Entfernte importierte globale Tabs','Products cleaned'=>'Bereinigte Produkte','You are not allowed to import tabs.'=>'Sie dürfen keine Tabs importieren.','Import from YIKES'=>'Import aus YIKES','WooCommerce tabs'=>'WooCommerce-Tabs','Rename, reorder or hide the standard tabs on every product (single products can hide them too, under Product data → Custom tabs). Leave a title empty to keep WooCommerce\'s title; in the Reviews title, %s becomes the number of reviews.'=>'Standard-Tabs bei allen Produkten umbenennen, sortieren oder ausblenden (einzelne Produkte können sie auch unter Produktdaten → Eigene Tabs ausblenden). Lassen Sie einen Titel leer, um den WooCommerce-Titel zu behalten; im Bewertungen-Titel wird %s durch die Anzahl der Bewertungen ersetzt.','Tab'=>'Tab','Title'=>'Titel','Priority of product tabs'=>'Priorität der Produkt-Tabs','The first tab added on a product gets this priority, the next one +1, and so on. 25 places them between Additional information and Reviews. Global tabs have their own priority.'=>'Der erste Tab eines Produkts erhält diese Priorität, der nächste +1 usw. 25 platziert sie zwischen Zusätzliche Informationen und Bewertungen. Globale Tabs haben eine eigene Priorität.','Display'=>'Anzeige','Keep Reviews as the last tab'=>'Bewertungen immer als letzten Tab','Repeat the tab title as a heading inside the tab (classic tabs; never inside accordions)'=>'Tab-Titel als Überschrift im Tab wiederholen (klassische Tabs; nie in Akkordeons)','Output FAQPage structured data for FAQ tabs that allow it (turn off if your SEO plugin already adds FAQ markup)'=>'Strukturierte FAQPage-Daten für FAQ-Tabs ausgeben, die es erlauben (deaktivieren, wenn Ihr SEO-Plugin bereits FAQ-Markup hinzufügt)','While YIKES Custom Product Tabs is still active, hide its copy of tabs that were imported'=>'Solange YIKES Custom Product Tabs aktiv ist, dessen Kopie importierter Tabs ausblenden','Uninstall'=>'Deinstallation','Delete all tabs and settings of this plugin when it is deleted from the Plugins screen'=>'Alle Tabs und Einstellungen dieses Plugins löschen, wenn es auf der Plugin-Seite gelöscht wird','Off by default, so deleting and reinstalling the plugin keeps your tabs. YIKES data is never touched.'=>'Standardmäßig aus, damit Ihre Tabs beim Löschen und Neuinstallieren erhalten bleiben. YIKES-Daten werden nie angefasst.','Copies the tabs of "Custom Product Tabs for WooCommerce" by YIKES: every product\'s tabs (in the same order, with the same content) and the saved tabs, which become global tabs. Products that used a saved tab are linked to the new global tab, so editing it updates them all. Saved tabs that the YIKES Pro add-on assigned to all products or to categories/tags keep those rules.'=>'Kopiert die Tabs von „Custom Product Tabs for WooCommerce“ von YIKES: die Tabs jedes Produkts (in derselben Reihenfolge, mit demselben Inhalt) und die gespeicherten Tabs, die zu globalen Tabs werden. Produkte, die einen gespeicherten Tab verwendet haben, werden mit dem neuen globalen Tab verknüpft, sodass eine Änderung alle aktualisiert. Gespeicherte Tabs, die das YIKES-Pro-Add-on allen Produkten oder Kategorien/Schlagwörtern zugewiesen hat, behalten diese Regeln.','YIKES data is only read. Nothing is changed or deleted, and YIKES keeps working until you deactivate it.'=>'YIKES-Daten werden nur gelesen. Nichts wird geändert oder gelöscht, und YIKES funktioniert weiter, bis Sie es deaktivieren.','Running it again is safe: tabs are never duplicated, and products whose YIKES tabs did not change are skipped.'=>'Ein erneuter Lauf ist sicher: Tabs werden nie doppelt angelegt, und Produkte mit unveränderten YIKES-Tabs werden übersprungen.','Tabs YIKES never showed (no title, or hidden by another tab with the same title) are imported switched off and listed below.'=>'Tabs, die YIKES nie angezeigt hat (ohne Titel oder durch einen anderen Tab mit gleichem Titel verdeckt), werden deaktiviert importiert und unten aufgelistet.','Large catalogues are handled in batches of 100 products. Command line: wp pnscripts-product-tabs import-yikes --dry-run'=>'Große Kataloge werden in Paketen zu 100 Produkten verarbeitet. Kommandozeile: wp pnscripts-product-tabs import-yikes --dry-run','Found:'=>'Gefunden:','%d product with YIKES tabs'=>'%d Produkt mit YIKES-Tabs' . "\0" . '%d Produkte mit YIKES-Tabs','YIKES plugin active'=>'YIKES-Plugin aktiv','YIKES plugin not active (data can still be imported)'=>'YIKES-Plugin nicht aktiv (Daten können trotzdem importiert werden)','last import: %s'=>'letzter Import: %s','Dry run (change nothing)'=>'Probelauf (nichts ändern)','Import now'=>'Jetzt importieren','Undo import'=>'Import rückgängig machen','Notes'=>'Hinweise','PN Scripts Product Tabs found tabs from Custom Product Tabs for WooCommerce (YIKES). Import them in one click; YIKES data stays untouched.'=>'PN Scripts Product Tabs hat Tabs aus Custom Product Tabs for WooCommerce (YIKES) gefunden. Importieren Sie sie mit einem Klick; die YIKES-Daten bleiben unverändert.','Review the import'=>'Import prüfen','Dismiss'=>'Ausblenden','Saved tab #%d has no title and was skipped.'=>'Gespeicherter Tab #%d hat keinen Titel und wurde übersprungen.','Saved tab "%1$s" was assigned by the taxonomy "%2$s", which is not supported; it is imported for the categories and tags only.'=>'Der gespeicherte Tab „%1$s“ wurde über die Taxonomie „%2$s“ zugewiesen, die nicht unterstützt wird; er wird nur für die Kategorien und Schlagwörter importiert.','Product #%d: a tab without a title (never shown by YIKES) was imported switched off.'=>'Produkt #%d: Ein Tab ohne Titel (von YIKES nie angezeigt) wurde deaktiviert importiert.','Product #%1$d: the tab "%2$s" was hidden by a later tab with the same title in YIKES; it was imported switched off.'=>'Produkt #%1$d: Der Tab „%2$s“ wurde in YIKES durch einen späteren Tab mit gleichem Titel verdeckt; er wurde deaktiviert importiert.','PN Scripts Product Tabs needs WooCommerce %s or newer to be active.'=>'PN Scripts Product Tabs benötigt ein aktives WooCommerce %s oder neuer.','Global product tabs'=>'Globale Produkt-Tabs','Global product tab'=>'Globaler Produkt-Tab','Product tabs'=>'Produkt-Tabs','Add global tab'=>'Globalen Tab hinzufügen','New global tab'=>'Neuer globaler Tab','Search global tabs'=>'Globale Tabs durchsuchen','No global tabs yet.'=>'Noch keine globalen Tabs.','No global tabs in the trash.'=>'Keine globalen Tabs im Papierkorb.','Global tab updated.'=>'Globaler Tab aktualisiert.','Global tab published.'=>'Globaler Tab veröffentlicht.','Reusable tabs shown on all products, on products in chosen categories or tags, or where added manually.'=>'Wiederverwendbare Tabs für alle Produkte, für Produkte in gewählten Kategorien oder Schlagwörtern oder dort, wo sie manuell hinzugefügt wurden.','Sorry, you are not allowed to view global product tabs.'=>'Sie dürfen globale Produkt-Tabs nicht ansehen.']];